import React from 'react';
import { Text, View } from 'react-native';
import { MeetingBadge, useMeetingStyles } from './meetingStyles';
import {
  RESPONSE_LABELS, SITUATION_LABELS, formatDateTime, formatDuration, formatTime,
  type AttendanceList, type AttendanceRow,
} from '../../utils/meetings';

interface Props { list: AttendanceList; }

const registeredBy = (name: string | null, owner: string) => (name && name !== owner ? ` (registrado por ${name})` : '');

/** Attendance list as generated by the president: who was invited, answered and when they came and left. */
export default function AttendanceListView({ list }: Props) {
  const { colors, styles } = useMeetingStyles();
  const color = (row: AttendanceRow) => row.situation === 'ABSENT' ? colors.danger : row.situation === 'PRESENT' ? colors.success : colors.warning;
  return (
    <View>
      <View style={styles.card}>
        <Text style={styles.cardTitle}>{list.title}</Text>
        <Text style={styles.subtitle}>{list.committeeName}</Text>
        <Text style={styles.subtitle}>{formatDateTime(list.startsAt)} até {formatDateTime(list.endsAt)}</Text>
        <View style={styles.badges}>
          <MeetingBadge text={`${list.totalPresent} presentes`} color={colors.success} />
          <MeetingBadge text={`${list.totalAbsent} ausentes`} color={colors.danger} />
          <MeetingBadge text={`${list.totalInvited} convidados`} />
        </View>
        {list.generatedAt ? <Text style={styles.hint}>Gerada em {formatDateTime(list.generatedAt)}{list.generatedByName ? ` por ${list.generatedByName}` : ''}.</Text> : null}
      </View>
      {list.rows.map(row => <View key={row.userId} style={styles.card}>
        <Text style={styles.cardTitle}>{row.userName}</Text>
        <View style={styles.badges}><MeetingBadge text={SITUATION_LABELS[row.situation]} color={color(row)} /></View>
        <Text style={styles.subtitle}>Convite: {RESPONSE_LABELS[row.response]}{row.responseComment ? ` (${row.responseComment})` : ''}</Text>
        <Text style={styles.subtitle}>Entrada: {row.enteredAt ? `${formatTime(row.enteredAt)}${registeredBy(row.enteredByName, row.userName)}` : 'não registrada'}</Text>
        <Text style={styles.subtitle}>Saída: {row.leftAt ? `${formatTime(row.leftAt)}${registeredBy(row.leftByName, row.userName)}` : 'não registrada'}</Text>
        {row.durationMinutes !== null ? <Text style={styles.subtitle}>Tempo na reunião: {formatDuration(row.durationMinutes)}</Text> : null}
      </View>)}
    </View>
  );
}
